import{_ as t,C as d,o as s,c as i,j as a,a as r,E as c,a5 as n}from"./chunks/framework.B1qnvv14.js";const E=JSON.parse('{"title":"Comandos","description":"","frontmatter":{"title":"Comandos"},"headers":[],"relativePath":"comandos.md","filePath":"comandos.md","lastUpdated":1792102410000}'),l={name:"comandos.md"};function p(h,e,u,m,k,g){const o=d("CopyOrDownloadAsMarkdownButtons");return s(),i("div",null,[e[0]||(e[0]=a("h1",{id:"comandos",tabindex:"-1"},[r("Comandos "),a("a",{class:"header-anchor",href:"#comandos","aria-label":'Permalink to "Comandos"'},"​")],-1)),c(o),e[1]||(e[1]=n('<p>Todo comando aceita <code>--help</code>.</p><h2 id="tasks" tabindex="-1">Tasks <a class="header-anchor" href="#tasks" aria-label="Permalink to &quot;Tasks&quot;">​</a></h2><h3 id="automacli-init-dir" tabindex="-1"><code>automacli init [DIR]</code> <a class="header-anchor" href="#automacli-init-dir" aria-label="Permalink to &quot;`automacli init [DIR]`&quot;">​</a></h3><p>Cria o perfil de um repositório a partir dos seus arquivos compose. Rode dentro de um checkout do repositório.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>--local</code></td><td>Grava <code>.automacli.yml</code> na raiz do repositório em vez de <code>~/.config/automacli/repos/</code>.</td></tr><tr><td><code>-y</code>, <code>--yes</code></td><td>Aceita as sugestões sem perguntar.</td></tr><tr><td><code>--force</code></td><td>Sobrescreve um perfil existente.</td></tr><tr><td><code>-g</code>, <code>--global</code></td><td>Só a configuração da máquina, sem perfil de repositório.</td></tr></tbody></table><p>Enquanto o <code>config.json</code> não tiver token do GitHub (ou com <code>--global</code>), o <code>init</code> abre um assistente para a configuração da máquina: diretório das tasks, token do GitHub, estratégia de clone (entre as que a máquina suporta) e notificações. Grava em <code>~/.config/automacli/config.json</code>.</p><p>Para o repositório, o <code>init</code> pergunta quais arquivos compose formam a stack, quais serviços são compartilhados (pré-seleciona bancos, caches e filas pela imagem ou pelo nome do serviço) e, no Linux, se o isolamento por systemd deve ser ligado. Inclui <code>.env</code> em <code>rewrite</code> quando existe e <code>Makefile</code> em <code>compose.wireInto</code> quando ele existe e chama <code>docker compose</code>.</p><h3 id="automacli-doctor" tabindex="-1"><code>automacli doctor</code> <a class="header-anchor" href="#automacli-doctor" aria-label="Permalink to &quot;`automacli doctor`&quot;">​</a></h3><p>Mostra o que a máquina oferece (git, Docker e Compose; btrfs, reflink, systemd, journal, notificações, clipboard) e qual estratégia de clone será usada. Veja <a href="./requisitos">Requisitos e ambiente</a>.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-r</code>, <code>--repo</code></td><td><code>owner/repo</code>: avalia a estratégia com o repo base desse repositório.</td></tr><tr><td><code>-j</code>, <code>--json</code></td><td>Saída em JSON.</td></tr></tbody></table><h3 id="automacli-base-convert-owner-repo" tabindex="-1"><code>automacli base convert OWNER/REPO</code> <a class="header-anchor" href="#automacli-base-convert-owner-repo" aria-label="Permalink to &quot;`automacli base convert OWNER/REPO`&quot;">​</a></h3><p>Converte o repo base em subvolume btrfs, para que os próximos clones usem snapshot (instantâneo). Aceita também um caminho. Não gasta disco e mantém o compartilhamento com as tasks existentes; leva cerca de um minuto. <code>-y</code>, <code>--yes</code> pula a confirmação.</p><h3 id="automacli-base-update-owner-repo" tabindex="-1"><code>automacli base update [OWNER/REPO]</code> <a class="header-anchor" href="#automacli-base-update-owner-repo" aria-label="Permalink to &quot;`automacli base update [OWNER/REPO]`&quot;">​</a></h3><p>Atualiza o repo base agora: <code>git pull --ff-only</code> da branch principal quando ela avançou, depois <code>baseRepo.regenerate</code> (se <code>autoUpdate.regenerate</code>), <code>baseRepo.autoUpdate.test</code> e, por último, <code>baseRepo.warmup</code> (se <code>autoUpdate.warmup</code>). <code>--force</code> regenera e testa mesmo sem commits novos. Sai com erro se um passo obrigatório falhar, mostrando as últimas linhas da saída; uma falha no pré-aquecimento só é registrada. Não mexe num repo base com alterações locais fora dos templates, nem num que outro processo esteja atualizando (<code>.automacli-update.lock</code> com menos de 2 h); nesses casos só avisa.</p><h3 id="automacli-base-warmup-owner-repo" tabindex="-1"><code>automacli base warmup [OWNER/REPO]</code> <a class="header-anchor" href="#automacli-base-warmup-owner-repo" aria-label="Permalink to &quot;`automacli base warmup [OWNER/REPO]`&quot;">​</a></h3><p>Roda só os comandos de <code>baseRepo.warmup</code> no repo base, sem pull, regeneração nem testes. Serve para aquecer caches na hora (depois de ligar o perfil) e para medir quanto tempo o pré-aquecimento leva. Sai com erro se algum comando falhar.</p><h3 id="automacli-base-status" tabindex="-1"><code>automacli base status</code> <a class="header-anchor" href="#automacli-base-status" aria-label="Permalink to &quot;`automacli base status`&quot;">​</a></h3><p>Últimas 5 atualizações (automáticas e manuais) de cada repo base: quando, quantos commits, quantos passos, duração e em qual comando falhou.</p><h3 id="automacli-profile" tabindex="-1"><code>automacli profile</code> <a class="header-anchor" href="#automacli-profile" aria-label="Permalink to &quot;`automacli profile`&quot;">​</a></h3><p>Mostra o perfil em vigor: de qual arquivo veio, os valores resolvidos e a tabela de portas.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-d</code>, <code>--dir</code></td><td>Diretório do repositório ou da task. Padrão: diretório atual.</td></tr><tr><td><code>-s</code>, <code>--slot</code></td><td>Slot usado na tabela de portas. Padrão: o do <code>.slot</code>, senão 1.</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ automacli profile --slot 2</span></span>\n<span class="line"><span>Repositório: minha-org/minha-api</span></span>\n<span class="line"><span>Perfil:      /home/voce/.config/automacli/repos/minha-org-minha-api.yml</span></span>\n<span class="line"><span>Projeto:     minha-api-slot2 (slot 2)</span></span>\n<span class="line"><span>...</span></span>\n<span class="line"><span>SERVIÇO  ORIGINAL  SLOT 2</span></span>\n<span class="line"><span>api      4000      4200</span></span>\n<span class="line"><span>db       5432      5432  (compartilhado)</span></span></code></pre></div><h3 id="automacli-clone-branch-f-owner-repo" tabindex="-1"><code>automacli clone BRANCH -f OWNER/REPO</code> <a class="header-anchor" href="#automacli-clone-branch-f-owner-repo" aria-label="Permalink to &quot;`automacli clone BRANCH -f OWNER/REPO`&quot;">​</a></h3><p>Cria uma task para a branch. Se a branch não existe no remoto, é criada localmente a partir da branch principal.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-f</code>, <code>--filter</code></td><td>Repositório no formato <code>owner/repo</code>. Obrigatório.</td></tr><tr><td><code>-d</code>, <code>--directory</code></td><td>Diretório onde criar a task. Padrão: <code>clonePath</code> da configuração.</td></tr><tr><td><code>-s</code>, <code>--slot</code></td><td>Força um número de slot. <code>0</code> mantém portas e projeto originais.</td></tr><tr><td><code>--no-slot</code></td><td>Não isola: sem override, sem reescrita, sem <code>.slot</code>.</td></tr><tr><td><code>--strategy</code></td><td><code>auto</code>, <code>snapshot</code>, <code>reflink</code>, <code>git-reference</code> ou <code>git</code>. Padrão: <code>cloneStrategy</code> do config. Veja <a href="./requisitos#como-as-tasks-sao-criadas">como as tasks são criadas</a>.</td></tr><tr><td><code>--no-reflink</code></td><td>Atalho para <code>--strategy git</code>.</td></tr><tr><td><code>--base-update</code></td><td>O que fazer com um repo base atrasado, sem perguntar: <code>regen</code> (pull e regenerar artefatos), <code>pull</code> (só o <code>git pull</code>) ou <code>skip</code> (usar como está).</td></tr><tr><td><code>--create-base</code> / <code>--no-create-base</code></td><td>Criar ou não o repo base quando ele não existe, sem perguntar. Sem base, o clone é por <code>git</code>.</td></tr><tr><td><code>--replace</code></td><td>Se a task já existe, apaga e recria sem perguntar.</td></tr><tr><td><code>-y</code>, <code>--yes</code></td><td>Sem prompts, com as respostas padrão: <code>--base-update regen</code> e <code>--create-base</code>. Não apaga task existente; para isso, <code>--replace</code>.</td></tr><tr><td><code>--json</code></td><td>Sem prompts; o progresso vai para o stderr e o stdout recebe só um JSON com o resultado.</td></tr></tbody></table><h4 id="sem-terminal-delegar-o-clone-a-uma-ia-ou-a-um-script" tabindex="-1">Sem terminal: delegar o clone a uma IA ou a um script <a class="header-anchor" href="#sem-terminal-delegar-o-clone-a-uma-ia-ou-a-um-script" aria-label="Permalink to &quot;Sem terminal: delegar o clone a uma IA ou a um script&quot;">​</a></h4><p>O clone tem três perguntas: repo base atrasado, repo base inexistente e task já existente. Cada uma tem uma flag que a responde. Sem terminal (stdin não é um TTY), ou com <code>--yes</code> ou <code>--json</code>, nada é perguntado: um repo base atrasado é usado como está (ou atualizado, com <code>--yes</code>), um repo base inexistente é criado, e uma task existente dá erro em vez de ser apagada, a menos que <code>--replace</code> esteja presente.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">automacli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minha-feature</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minha-org/minha-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base-update</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> regen</span></span></code></pre></div><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;branch&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minha-feature&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;owner&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minha-org&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;repo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minha-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;directory&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/home/voce/tasks/task-minha-feature-minha-org-minha-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;strategy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;snapshot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;slot&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;composeProjectName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minha-api-slot3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ports&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;web&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3300</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]},</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sharedServices&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;db&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;redis&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;baseRepo&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/home/voce/tasks/task-base-minha-org-minha-api&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;behindBefore&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;regen&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;update&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;updated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>baseRepo.update</code> é o status da atualização (<code>updated</code>, <code>up-to-date</code>, <code>failed</code>, <code>skipped-dirty</code>, <code>locked</code>) ou <code>null</code> quando não houve. Em erro, o stdout recebe <code>{&quot;ok&quot;: false, &quot;error&quot;: &quot;...&quot;}</code> e o código de saída é 1.</p><p>Ao final, <code>cd &lt;diretório da task&gt;</code> vai para a área de transferência (<code>wl-copy</code>, <code>xclip</code>, <code>xsel</code>, <code>pbcopy</code> ou <code>clip.exe</code>, o que existir); sem nenhum deles, o comando é só impresso.</p><p>O passo a passo está em <a href="./como-funciona">Como funciona</a>.</p><h3 id="automacli-override" tabindex="-1"><code>automacli override</code> <a class="header-anchor" href="#automacli-override" aria-label="Permalink to &quot;`automacli override`&quot;">​</a></h3><p>Regenera o override da task atual com o estado de agora e, com ElasticMQ compartilhado, garante as filas do slot (<a href="./perfil#queues"><code>queues</code></a>). Com <code>shared.host: base</code> (padrão), os serviços compartilhados ficam fora da stack e, se nenhum estiver no ar, o comando sobe a stack compartilhada a partir do repo base; com <code>shared.host: first-task</code>, eles só são desabilitados quando outra task já os roda. Rode antes de subir a stack.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-d</code>, <code>--dir</code></td><td>Diretório da task. Padrão: diretório atual.</td></tr><tr><td><code>-q</code>, <code>--quiet</code></td><td>Sem saída em caso de sucesso, para uso em Makefiles.</td></tr></tbody></table><p>Em um diretório sem <code>.slot</code> não faz nada.</p><h3 id="automacli-shared-up-status-down" tabindex="-1"><code>automacli shared up|status|down</code> <a class="header-anchor" href="#automacli-shared-up-status-down" aria-label="Permalink to &quot;`automacli shared up|status|down`&quot;">​</a></h3><p>Serviços compartilhados (banco, cache, DNS) rodando a partir do repo base. <code>status</code> mostra onde cada um está; <code>up</code> sobe o que falta e move para o repo base o que estiver rodando dentro de uma task; <code>down</code> para todos (pede confirmação).</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-r</code>, <code>--repo</code></td><td><code>owner/repo</code>. Padrão: o do diretório atual.</td></tr><tr><td><code>-y</code>, <code>--yes</code></td><td>Não pede confirmação no <code>down</code>.</td></tr></tbody></table><p>O <code>branches</code> recusa remover o repo base enquanto ele hospedar os compartilhados.</p><h3 id="automacli-branches" tabindex="-1"><code>automacli branches</code> <a class="header-anchor" href="#automacli-branches" aria-label="Permalink to &quot;`automacli branches`&quot;">​</a></h3><p>Lista as tasks com tamanho e data, em uma interface interativa que permite renomear e remover.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>--no-tui</code></td><td>Imprime uma tabela em vez da interface interativa.</td></tr><tr><td><code>-s</code>, <code>--sort</code></td><td><code>date</code> (padrão), <code>size</code> ou <code>name</code>.</td></tr><tr><td><code>-d</code>, <code>--remove</code></td><td>Remove a task com esse nome de diretório, ou um trecho que case com um único diretório.</td></tr><tr><td><code>-r</code>, <code>--rename</code> com <code>-t</code>, <code>--to</code></td><td>Renomeia uma task (mesma regra de nome ou trecho). Para a stack antes.</td></tr><tr><td><code>-y</code>, <code>--yes</code></td><td>Não pede confirmação no <code>--remove</code>. É o que o painel e scripts usam.</td></tr></tbody></table><p>Remover uma task para a stack dela antes (<code>docker compose -p &lt;projeto&gt; down</code>), apaga as filas do slot num ElasticMQ compartilhado (<a href="./perfil#queues"><code>queues</code></a>), retoma a posse de arquivos criados por containers e apaga o diretório. Em btrfs com <code>user_subvol_rm_allowed</code>, um snapshot some na hora; senão, a task é movida para <code>&lt;clonePath&gt;/.lixeira/</code> (um rename, instantâneo) e apagada em segundo plano, então o slot fica livre na hora e o disco volta em alguns minutos. Restos de uma remoção interrompida por reinício são apagados na próxima.</p><h3 id="automacli-oom" tabindex="-1"><code>automacli oom</code> <a class="header-anchor" href="#automacli-oom" aria-label="Permalink to &quot;`automacli oom`&quot;">​</a></h3><p>Lista os serviços e processos das tasks que foram mortos por falta de memória, lendo o journal do sistema. Sem <code>journalctl</code>, usa o <code>OOMKilled</code> que o Docker registra, sem motivo nem slice.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>--since</code></td><td>Período: <code>30min</code>, <code>2h</code>, <code>7d</code>, <code>today</code> ou uma data. Padrão: <code>24h</code>.</td></tr><tr><td><code>-s</code>, <code>--slot</code></td><td>Só as mortes de um slot.</td></tr><tr><td><code>-j</code>, <code>--json</code></td><td>Saída em JSON.</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ automacli oom --since 3h --slot 4</span></span>\n<span class="line"><span>QUANDO                O QUÊ                       CAUSA   MOTIVO</span></span>\n<span class="line"><span>05/10/2026, 17:56:57  marketplace-front (slot 4)  oomd    memory pressure for /automacli.slice being 83.39% &gt; 60.00% for &gt; 10s</span></span>\n<span class="line"><span>05/10/2026, 17:57:26  necso-front (slot 4)        oomd    memory pressure for /automacli.slice/automacli-slot4.slice being 62.69% &gt; 60.00% for &gt; 10s</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>2 morte(s). Mais afetados:</span></span>\n<span class="line"><span>    1×  marketplace-front (slot 4)</span></span>\n<span class="line"><span>    1×  necso-front (slot 4)</span></span></code></pre></div><p>A coluna <strong>CAUSA</strong> diz quem matou: <code>oomd</code> é o systemd-oomd reagindo à pressão de memória no slice; <code>kernel</code> é o OOM killer do kernel: o teto <code>MemoryMax</code> de um slice ou a memória da máquina esgotada. O <strong>MOTIVO</strong> mostra qual slice estourou: o do slot ou o global <code>automacli.slice</code> (todas as stacks juntas). Detalhes em <a href="./isolamento#saber-o-que-foi-morto">Isolamento de recursos</a>.</p><h2 id="monitor" tabindex="-1">Monitor <a class="header-anchor" href="#monitor" aria-label="Permalink to &quot;Monitor&quot;">​</a></h2><h3 id="automacli-monitor" tabindex="-1"><code>automacli monitor</code> <a class="header-anchor" href="#automacli-monitor" aria-label="Permalink to &quot;`automacli monitor`&quot;">​</a></h3><p>Sobe o servidor de monitoramento. Veja <a href="./monitor">Monitor</a>.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-p</code>, <code>--port</code></td><td>Porta HTTP. Padrão: <code>7777</code>.</td></tr><tr><td><code>--http-only</code></td><td>Só o servidor HTTP, sem a dica sobre o MCP. É o que o serviço systemd usa.</td></tr><tr><td><code>--watch</code> / <code>--no-watch</code></td><td>Recarrega <code>config.json</code>, <code>repos/*.yml</code> e <code>templates/</code> quando mudam. Ligado por padrão.</td></tr><tr><td><code>--notify</code> / <code>--no-notify</code></td><td>Liga ou desliga as notificações de desktop, vencendo o <code>notifications</code> do <code>config.json</code>.</td></tr><tr><td><code>--mcp-only</code></td><td>Só o servidor MCP, por stdio.</td></tr><tr><td><code>--no-notify</code></td><td>Desliga a notificação de desktop quando um serviço é morto por falta de memória.</td></tr></tbody></table><h3 id="automacli-mcp-setup-config-status-cliente" tabindex="-1"><code>automacli mcp setup|config|status [CLIENTE]</code> <a class="header-anchor" href="#automacli-mcp-setup-config-status-cliente" aria-label="Permalink to &quot;`automacli mcp setup|config|status [CLIENTE]`&quot;">​</a></h3><p>Liga o MCP do monitor a um assistente de IA. Clientes: <code>claude-code</code>, <code>codex</code>, <code>gemini</code>, <code>cursor</code>, <code>windsurf</code>, <code>vscode</code>, <code>claude-desktop</code> ou <code>all</code> (todos os encontrados na máquina). Veja <a href="./mcp">MCP para agentes de IA</a>.</p><table tabindex="0"><thead><tr><th>Ação</th><th>O que faz</th></tr></thead><tbody><tr><td><code>setup [CLIENTE]</code></td><td>Registra o servidor pela CLI do cliente quando existe (<code>claude mcp add</code> etc.), senão grava o arquivo de configuração dele, preservando outros servidores. Sem cliente, pergunta entre os instalados.</td></tr><tr><td><code>config [CLIENTE]</code></td><td>Imprime o trecho para colar: JSON de <code>mcpServers</code> (padrão), TOML para <code>codex</code>, JSON de <code>servers</code> para <code>vscode</code>.</td></tr><tr><td><code>status</code></td><td>Para cada cliente: ligado, instalado sem o MCP, ou não encontrado.</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>--dry-run</code></td><td>Mostra o comando que rodaria ou o arquivo que gravaria, sem fazer nada.</td></tr><tr><td><code>--file</code></td><td>Grava no arquivo de configuração mesmo quando o cliente tem CLI.</td></tr></tbody></table><h3 id="automacli-monitor-setup" tabindex="-1"><code>automacli monitor setup</code> <a class="header-anchor" href="#automacli-monitor-setup" aria-label="Permalink to &quot;`automacli monitor setup`&quot;">​</a></h3><p>Instala o monitor como serviço systemd do usuário, iniciado no login.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-p</code>, <code>--port</code></td><td>Porta HTTP. Padrão: <code>7777</code>.</td></tr><tr><td><code>--status</code></td><td>Mostra o estado do serviço.</td></tr><tr><td><code>--remove</code></td><td>Remove o serviço.</td></tr></tbody></table><h2 id="utilitarios" tabindex="-1">Utilitários <a class="header-anchor" href="#utilitarios" aria-label="Permalink to &quot;Utilitários&quot;">​</a></h2><h3 id="automacli-update" tabindex="-1"><code>automacli update</code> <a class="header-anchor" href="#automacli-update" aria-label="Permalink to &quot;`automacli update`&quot;">​</a></h3><p>Atualiza o próprio automacli para a última release, respeitando o versionamento semântico: correções (<code>patch</code>) e novidades compatíveis (<code>minor</code>) são aplicadas; um salto de versão maior (<code>major</code>), que pode trazer mudanças incompatíveis, só com <code>--major</code>.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-c</code>, <code>--check</code></td><td>Só verifica: diz se há versão nova e de que tipo, sem instalar.</td></tr><tr><td><code>--major</code></td><td>Permite atualizar para uma versão maior.</td></tr><tr><td><code>--json</code></td><td>Resultado em JSON: <code>current</code>, <code>latest</code>, <code>diff</code>, <code>newer</code>, <code>installMethod</code>, <code>action</code>, <code>command</code>.</td></tr></tbody></table><p>O que o comando faz depende de como esta cópia foi instalada:</p><table tabindex="0"><thead><tr><th>Instalação</th><th>O que acontece</th></tr></thead><tbody><tr><td>Executável do instalador (<code>~/.local/share/automacli</code>)</td><td>Baixa o tarball da versão nova, confere o SHA-256 pelo <code>SHA256SUMS</code> do release e troca o diretório de uma vez, como o <code>install.sh</code>.</td></tr><tr><td>Pacote da distribuição (<code>/opt/automacli</code>)</td><td>Mostra o comando do gerenciador (<code>apt</code>, <code>dnf</code>, <code>zypper</code> ou <code>yay</code>), que é quem deve atualizar.</td></tr><tr><td>Código-fonte</td><td>Mostra <code>git pull &amp;&amp; pnpm install &amp;&amp; pnpm build</code>.</td></tr></tbody></table><p>Além do comando, qualquer execução no terminal avisa, no máximo uma vez por dia, quando existe versão nova (a consulta fica em cache em <code>~/.cache/automacli/update-check.json</code>). O aviso não aparece com <code>--json</code>, fora de um terminal, no monitor, nem com <code>AUTOMACLI_NO_UPDATE_CHECK=1</code>.</p><h3 id="automacli-outdated" tabindex="-1"><code>automacli outdated</code> <a class="header-anchor" href="#automacli-outdated" aria-label="Permalink to &quot;`automacli outdated`&quot;">​</a></h3><p>Procura pacotes npm desatualizados no diretório atual.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-d</code>, <code>--directory</code></td><td>Diretório a examinar.</td></tr><tr><td><code>-f</code>, <code>--filter</code></td><td>Regex de nomes de pacote (ex.: <code>^@minha-org</code>). Padrão: <code>packageFilter</code> da configuração.</td></tr><tr><td><code>--no-dev</code></td><td>Ignora <code>devDependencies</code>.</td></tr><tr><td><code>-j</code>, <code>--json</code></td><td>Saída em JSON.</td></tr></tbody></table><h3 id="automacli-cleanup" tabindex="-1"><code>automacli cleanup</code> <a class="header-anchor" href="#automacli-cleanup" aria-label="Permalink to &quot;`automacli cleanup`&quot;">​</a></h3><p>Apaga diretórios descartáveis (<code>node_modules</code>, <code>dist</code>, <code>coverage</code>...) a partir do diretório atual.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Descrição</th></tr></thead><tbody><tr><td><code>-p</code>, <code>--patterns</code></td><td>Nomes de diretório a apagar, separados por espaço.</td></tr><tr><td><code>-s</code>, <code>--save &lt;padrões&gt;</code></td><td>Só grava os padrões em <code>~/.cleanup_patterns</code>, usados nas próximas execuções, e sai sem apagar nada. Não combina com <code>-p</code> nem com <code>--verdaccio*</code>.</td></tr><tr><td><code>-i</code>, <code>--interactive</code> / <code>--no-interactive</code></td><td>Pergunta antes de apagar. Ligado por padrão; <code>--no-interactive</code> exige <code>-p</code>.</td></tr><tr><td><code>--verdaccioAll</code></td><td>Apaga todo o armazenamento do Verdaccio (<code>verdaccioStoragePath</code>).</td></tr><tr><td><code>--verdaccioScope</code></td><td>Apaga só os pacotes de um escopo, ex.: <code>@minha-org</code>. Faz <code>sudo chown</code> do armazenamento antes de apagar.</td></tr><tr><td><code>-v</code>, <code>--verbose</code></td><td>Mostra no spinner o diretório sendo removido.</td></tr></tbody></table><h3 id="automacli-setup-branch" tabindex="-1"><code>automacli setup [BRANCH]</code> <a class="header-anchor" href="#automacli-setup-branch" aria-label="Permalink to &quot;`automacli setup [BRANCH]`&quot;">​</a></h3><p>Faz <code>stash</code>, troca para a branch principal, <code>pull</code> e <code>stash apply</code> no repositório atual; com <code>BRANCH</code>, repete para essa branch. Com <code>all</code>, faz o mesmo em todos os repositórios de <code>setup.repos</code> da <a href="./instalacao#configuracao-global">configuração global</a>.</p><p>A branch principal é a de <code>origin/HEAD</code> (senão <code>main</code>), salvo quando o caminho contém uma chave de <code>setup.branchOverrides</code>.</p>',76))])}const q=t(l,[["render",p]]);export{E as __pageData,q as default};
